def solve_small(cards):
    memo = {}

    def get_minimax(current_cards, s1, s2, is_grogg_turn):
        state = (tuple(sorted(current_cards)), s1, s2, is_grogg_turn)
        if state in memo:
            return memo[state]

        if not current_cards:
            return abs(s1 - s2)

        if is_grogg_turn:
            # Grogg wants to minimize the final difference
            res = float('inf')
            for i, card in enumerate(current_cards):
                remaining = current_cards[:i] + current_cards[i+1:]
                # Grogg can put 'card' in Pile 1 or Pile 2
                res = min(res, get_minimax(remaining, s1 + card, s2, False))
                res = min(res, get_minimax(remaining, s1, s2 + card, False))
            memo[state] = res
            return res
        else:
            # Winnie wants to maximize the final difference
            res = float('-inf')
            for i, card in enumerate(current_cards):
                remaining = current_cards[:i] + current_cards[i+1:]
                # Winnie can put 'card' in Pile 1 or Pile 2
                res = max(res, get_minimax(remaining, s1 + card, s2, True))
                res = max(res, get_minimax(remaining, s1, s2 + card, True))
            memo[state] = res
            return res

    return get_minimax(list(cards), 0, 0, True)

